import{_ as a,a0 as d,w as o,s,I as e,x as i,ao as p,a1 as n,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"LFCS 系列第三讲：归档/压缩文件及目录、设置文件属性和搜索文件 | LCTT x X-CMD","titleTemplate":false,"description":"LFCS 系列第三讲：归档/压缩文件及目录、设置文件属性和搜索文件 | LCTT (LFCS) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"LFCS 系列第三讲：归档/压缩文件及目录、设置文件属性和搜索文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"LFCS 系列第三讲：归档/压缩文件及目录、设置文件属性和搜索文件 | LCTT (LFCS) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"LFCS/Part 3 - LFCS--How to Archive or Compress Files and Directories Setting File Attributes and Finding Files in Linux","title":"LFCS 系列第三讲：归档/压缩文件及目录、设置文件属性和搜索文件","tag":"LFCS","desc":""},"relativePath":"LFCS/Part 3 - LFCS--How to Archive or Compress Files and Directories Setting File Attributes and Finding Files in Linux.md","filePath":"[post].md"}'),m={name:"LFCS/Part 3 - LFCS--How to Archive or Compress Files and Directories Setting File Attributes and Finding Files in Linux.md"};function f(g,t,u,x,c,w){const l=d("Link");return o(),s("div",null,[t[20]||(t[20]=e("h1",{id:"lfcs-系列第三讲-归档-压缩文件及目录、设置文件属性和搜索文件",tabindex:"-1"},[i("LFCS 系列第三讲：归档/压缩文件及目录、设置文件属性和搜索文件 "),e("a",{class:"header-anchor",href:"#lfcs-系列第三讲-归档-压缩文件及目录、设置文件属性和搜索文件","aria-label":"Permalink to “LFCS 系列第三讲：归档/压缩文件及目录、设置文件属性和搜索文件”"},"​")],-1)),t[21]||(t[21]=e("p",null,"最近，Linux 基金会发起了一个全新的 LFCS（Linux Foundation Certified Sysadmin，Linux 基金会认证系统管理员）认证，旨在让遍布全世界的人都有机会参加该认证的考试，通过考试的人将表明他们有能力在 Linux 上执行基本的中级系统管理任务。这项认证包括了对已运行的系统和服务的支持、一流水平的问题解决和分析以及决定何时将问题反映给工程师团队的能力。",-1)),t[22]||(t[22]=e("p",null,[e("img",{src:"http://www.tecmint.com/wp-content/uploads/2014/10/lfcs-Part-3.png",alt:"Linux Foundation Certified Sysadmin – Part 3"})],-1)),t[23]||(t[23]=e("p",null,[e("em",null,"LFCS 系列第三讲")],-1)),t[24]||(t[24]=e("p",null,"请看以下视频，这里边讲给出 Linux 基金会认证程序的一些想法。",-1)),t[25]||(t[25]=e("p",null,"注：youtube 视频",-1)),t[26]||(t[26]=e("iframe",{width:"720",height:"405",frameborder:"0",allowfullscreen:"allowfullscreen",src:"//www.youtube.com/embed/Y29qZ71Kicg"},null,-1)),t[27]||(t[27]=p(`<p>本讲是系列教程中的第三讲，在这一讲中，我们会涵盖如何在文件系统中归档/压缩文件及目录、设置文件属性和搜索文件等内容，这些都是 LFCS 认证中必须掌握的知识。</p><h3 id="归档和压缩的相关工具" tabindex="-1">归档和压缩的相关工具 <a class="header-anchor" href="#归档和压缩的相关工具" aria-label="Permalink to “归档和压缩的相关工具”">​</a></h3><p>文件归档工具将一堆文件整合到一个单独的归档文件之后，我们可以将归档文件备份到不同类型的介质或者通过网络传输和发送 Email 来备份。在 Linux 中使用频率最高的归档实用工具是 tar。当归档工具和压缩工具一起使用的时候，可以减少同一文件和信息在硬盘中的存储空间。</p><h4 id="tar-使用工具" tabindex="-1">tar 使用工具 <a class="header-anchor" href="#tar-使用工具" aria-label="Permalink to “tar 使用工具”">​</a></h4><p>tar 将一组文件打包到一个单独的归档文件（通常叫做 tar 文件或者 tarball）。tar 这个名称最初代表磁带存档程序（tape archiver），但现在我们可以用它来归档任意类型的可读写介质上边的数据，而不是只能归档磁带数据。tar 通常与 gzip、bzip2 或者 xz 等压缩工具一起使用，生成一个压缩的 tarball。</p><p><strong>基本语法：</strong></p><pre><code># tar [选项] [路径名 ...]
</code></pre><p>其中 ... 代表指定哪些文件进行归档操作的表达式</p><h4 id="tar-的常用命令" tabindex="-1">tar 的常用命令 <a class="header-anchor" href="#tar-的常用命令" aria-label="Permalink to “tar 的常用命令”">​</a></h4><div class="table-wrap"><table><thead><tr><th>长选项</th><th style="text-align:center;">简写</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td>-create</td><td style="text-align:center;">c</td><td style="text-align:left;">创建 tar 归档文件</td></tr><tr><td>-concatenate</td><td style="text-align:center;">A</td><td style="text-align:left;">将一存档与已有的存档合并</td></tr><tr><td>-append</td><td style="text-align:center;">r</td><td style="text-align:left;">把要存档的文件追加到归档文件的末尾</td></tr><tr><td>-update</td><td style="text-align:center;">u</td><td style="text-align:left;">更新新文件到归档文件中去</td></tr><tr><td>-diff 或 -compare</td><td style="text-align:center;">d</td><td style="text-align:left;">比较存档与当前文件的不同之处</td></tr><tr><td>-file archive</td><td style="text-align:center;">f</td><td style="text-align:left;">使用档案文件或归档设备</td></tr><tr><td>-list</td><td style="text-align:center;">t</td><td style="text-align:left;">列出 tarball 中的内容</td></tr><tr><td>-extract 或 -get</td><td style="text-align:center;">x</td><td style="text-align:left;">从归档文件中释放文件</td></tr></tbody></table></div><h4 id="常用的操作修饰符" tabindex="-1">常用的操作修饰符 <a class="header-anchor" href="#常用的操作修饰符" aria-label="Permalink to “常用的操作修饰符”">​</a></h4><p>注：表格</p><div class="table-wrap"><table><thead><tr><th>长选项</th><th style="text-align:center;">缩写</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td>-directory dir</td><td style="text-align:center;">C</td><td style="text-align:left;">执行归档操作前，先转到指定目录</td></tr><tr><td>-same-permissions</td><td style="text-align:center;">p</td><td style="text-align:left;">保持原始的文件权限</td></tr><tr><td>-verbose</td><td style="text-align:center;">v</td><td style="text-align:left;">列出所有的读取或提取的文件。但这个标识符与 -list 一起使用的时候，还会显示出文件大小、属主和时间戳的信息</td></tr><tr><td>-verify</td><td style="text-align:center;">W</td><td style="text-align:left;">写入存档后进行校验</td></tr><tr><td>-exclude file</td><td style="text-align:center;"></td><td style="text-align:left;">不把指定文件包含在内</td></tr><tr><td>-exclude=pattern</td><td style="text-align:center;">X</td><td style="text-align:left;">以PATTERN模式排除文件</td></tr><tr><td>-gzip 或 -gunzip</td><td style="text-align:center;">z</td><td style="text-align:left;">通过gzip压缩归档</td></tr><tr><td>-bzip2</td><td style="text-align:center;">j</td><td style="text-align:left;">通过bzip2压缩归档</td></tr><tr><td>-xz</td><td style="text-align:center;">J</td><td style="text-align:left;">通过xz压缩归档</td></tr></tbody></table></div><p>Gzip 是最古老的压缩工具，压缩率最小，bzip2 的压缩率稍微高一点。另外，xz 是最新的压缩工具，压缩率最好。xz 具有最佳压缩率的代价是：完成压缩操作花费最多时间，压缩过程中占有较多系统资源。</p><p>通常，通过这些工具压缩的 tar 文件相应的具有 .gz、.bz2 或 .xz的扩展名。在下列的例子中，我们使用 file1、file2、file3、file4 和 file5 进行演示。</p><p><strong>通过 gzip、bzip2 和 xz 压缩归档</strong></p><p>归档当前工作目录的所有文件，并以 gzip、bzip2 和 xz 压缩刚刚的归档文件（请注意，用正则表达式来指定哪些文件应该归档——这是为了防止将归档工具包前一步生成的文件打包进来）。</p><pre><code># tar czf myfiles.tar.gz file[0-9]
# tar cjf myfiles.tar.bz2 file[0-9]
# tar cJf myfile.tar.xz file[0-9]
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Compress-Multiple-Files.png" alt="Compress Multiple Files Using tar"></p><p><em>压缩多个文件</em></p><p><strong>列举 tarball 中的内容和更新/追加文件到归档文件中</strong></p><p>列举 tarball 中的内容，并显示相同信息为一个详细目录清单。注意，不能直接向压缩的归档文件更新/追加文件（若你需要向压缩的 tarball 中更新/追加文件，需要先解压 tar 文件后再进行操作，然后重新压缩）。</p><pre><code># tar tvf [tarball]
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/List-Archive-Content.png" alt="Check Files in tar Archive"></p><p><em>列举归档文件中的内容</em></p><p>运行一下任意一条命令：</p><pre><code># gzip -d myfiles.tar.gz	[#1]
# bzip2 -d myfiles.tar.bz2	[#2]
# xz -d myfiles.tar.xz 		[#3]
</code></pre><p>然后：</p><pre><code># tar --delete --file myfiles.tar file4 (删除tarball中的file4)
# tar --update --file myfiles.tar file4 (更新tarball中的file4)
</code></pre><p>和</p><pre><code># gzip myfiles.tar		[ 如果你运行 #1 命令 ]
# bzip2 myfiles.tar		[ 如果你运行 #2 命令 ]
# xz myfiles.tar 		[ 如果你运行 #3 命令 ]
</code></pre><p>最后</p><pre><code># tar tvf [tarball] #again
</code></pre><p>将 file4 修改后的日期和时间与之前显示的对应信息进行比较</p><p><strong>排除文件类型</strong></p><p>假设你现在需要备份用户的家目录。一个有经验的系统管理员会选择忽略所有视频和音频文件再备份（也可能是公司规定）。</p><p>可能你最先想到的方法是在备份的时候，忽略扩展名为 .mp3 和 .mp4（或者其他格式）的文件。但如果你有些自作聪明的用户将扩展名改为 .txt 或者 .bkp，那你的方法就不灵了。为了发现并排除音频或者视频文件，你需要先检查文件类型。以下 shell 脚本可以代你完成类型检查：</p><pre><code>#!/bin/bash
# 把需要进行备份的目录传递给 $1 参数.
DIR=$1
# 排除文件类型中包含了 mpeg 字符串的文件，然后创建 tarball 并进行压缩。
# -若文件类型中包含 mpeg 字符串， $?（最后执行的命令的退出状态）返回 0，然后文件名被定向到排除选项。否则返回 1。
# -若 $? 等于 0，该文件从需要备份文件的列表排除。
tar X &lt;(for i in $DIR/*; do file $i | grep -i mpeg; if [ $? -eq 0 ]; then echo $i; fi;done) -cjf backupfile.tar.bz2 $DIR/*
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Exclude-Files-in-Tar.png" alt="Exclude Files in tar Archive"></p><p><em>排除文件进行备份</em></p><p><strong>使用 tar 保持文件的原有权限进行恢复</strong></p><p>通过以下命令，你可以保留文件的权限将备份文件恢复到原始用户的家目录（本例是 user_restore）。</p><pre><code># tar xjf backupfile.tar.bz2 --directory user_restore --same-permissions
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Restore-tar-Backup-Files.png" alt="Restore Files from tar Archive"></p><p><em>从归档文件中恢复</em></p><p><strong>扩展阅读：</strong></p>`,46)),e("ul",null,[e("li",null,[n(l,{href:"http://www.tecmint.com/18-tar-command-examples-in-linux/"},{default:r(()=>[...t[0]||(t[0]=[i("18 tar Command Examples in Linux",-1)])]),_:1})]),e("li",null,[n(l,{href:"http://www.tecmint.com/dtrx-an-intelligent-archive-extraction-tar-zip-cpio-rpm-deb-rar-tool-for-linux/"},{default:r(()=>[...t[1]||(t[1]=[i("Dtrx – An Intelligent Archive Tool for Linux",-1)])]),_:1})])]),t[28]||(t[28]=p(`<h3 id="通过-find-命令搜索文件" tabindex="-1">通过 find 命令搜索文件 <a class="header-anchor" href="#通过-find-命令搜索文件" aria-label="Permalink to “通过 find 命令搜索文件”">​</a></h3><p>find 命令用于递归搜索目录树中包含指定字符的文件和目录，然后在屏幕显示出于指定字符相匹配的文件和目录，或者在匹配项进行其他操作。</p><p>通常，我们通过文件名、文件的属主、属组、类型权限、日期及大小来搜索。</p><h4 id="基本语法" tabindex="-1">基本语法：#### <a class="header-anchor" href="#基本语法" aria-label="Permalink to “基本语法：####”">​</a></h4><pre><code># find [需搜索的目录] [表达式]
</code></pre><p><strong>通过文件大小递归搜索文件</strong></p><p>以下命令会搜索当前目录（.）及其下两层子目录（-maxdepth 3，包含当前目录及往下两层的子目录）中大于 2 MB（-size +2M）的所有文件（-f）。</p><pre><code># find . -maxdepth 3 -type f -size +2M
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Find-Files-Based-on-Size.png" alt="Find Files by Size in Linux"> * 通过文件大小搜索文件*</p><p><strong>搜索符合一定规则的文件并将其删除</strong></p><p>有时候，777 权限的文件通常为外部攻击者打开便利之门。不管是以何种方式，让所有人都可以对文件进行任意操作都是不安全的。对此，我们采取一个相对激进的方法——删除这些文件（&#39;{}&#39; + 用来“聚集”搜索的结果）。</p><pre><code># find /home/user -perm 777 -exec rm &#39;{}&#39; +
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Find-Files-with-777-Permission.png" alt="Find all 777 Permission Files"></p><p><em>搜索 777 权限的文件</em></p><p><strong>按访问时间和修改时间搜索文件</strong></p><p>搜索 /etc 目录下访问时间（-atime）或修改时间（-mtime）大于（+180）或小于（-180） 6 个月或者刚好（180） 6 个月的配置文件。</p><p>按照下面例子对命令进行修改：</p><pre><code># find /etc -iname &quot;*.conf&quot; -mtime -180 -print
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Find-Modified-Files.png" alt="Find Files by Modification Time"></p><p><em>按修改时间搜索文件</em></p>`,20)),e("ul",null,[e("li",null,[t[3]||(t[3]=i("扩展阅读： ",-1)),n(l,{href:"http://www.tecmint.com/35-practical-examples-of-linux-find-command/"},{default:r(()=>[...t[2]||(t[2]=[i("35 Practical Examples of Linux ‘find’ Command",-1)])]),_:1})])]),t[29]||(t[29]=p(`<h3 id="文件权限及基本属性" tabindex="-1">文件权限及基本属性 <a class="header-anchor" href="#文件权限及基本属性" aria-label="Permalink to “文件权限及基本属性”">​</a></h3><p>ls -l 命令输出的前 10 位字符是文件的属性，其中第一个字符用来表明文件的类型。</p><ul><li>– : 普通文件</li><li>-d : 目录</li><li>-l : 符号链接</li><li>-c : 字符设备 (它将数据作为字节流处理，如terminal)</li><li>-b : 块设备 (在块设备中处理数据，如存储设备)</li></ul><p>接下来表示文件属性的 9 位字符叫做文件的读写模式，代表文件属主、同组用户和其他用户（通常指的是“外部世界”）对应的读（r）、写（w）和执行（x）权限。</p><p>文件的写权限允许对应的用户对文件进行打开和读写，对于同时设置了执行权限的目录，对应用户可以列举出该目录的内容。另外，文件的执行权限允许将文件当做是一个可执行程序来运行，而目录的执行权限则是允许用户进入和退出该目录。</p><p>文件的权限通过 chown 命令来更改，其基本语法如下：</p><pre><code># chmod [new_mode] file
</code></pre><p>new_mode 可以是 3 位八进制数值或者对应权限的表达式。</p><p>八进制数值可以从二进制数值进行等值转换，通过下列方法来计算文件属主、同组用户和其他用户权限对应的二进制数值：</p><p>一个确定权限的二进制数值表现为 2 的幂（r=2^2，w=2^1，x=2^0），当权限省缺时，二进制数值为 0。如下：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/File-Permissions.png" alt="Linux File Permissions"></p><p><em>文件权限</em></p><p>使用八进制数值设置上图的文件权限，请输入：</p><pre><code># chmod 744 myfile
</code></pre><p>通过 u、g 和 o 分别代表用户、同组用户和其他用户，然后你也可以使用权限表达式来单独对用户设置文件的权限模式。也可以通过 a 代表所有用户，然后设置文件权限。通过 + 号或者 - 号相应的赋予或移除文件权限。</p><p><strong>为所有用户撤销一个 shell 脚本的执行权限</strong></p><p>正如之前解释的那样，我们可以通过 - 号为需要移除权限的属主、同组用户、其他用户或者所有用户去掉指定的文件权限。下面命令中的短横线（-）可以理解为：移除（-）所有用户（a）的 backup.sh 文件执行权限（x）。</p><pre><code># chmod a-x backup.sh
</code></pre><p>下面演示为文件属主、同组用户赋予读、写和执行权限，并赋予其他用户读权限。</p><p>当我们使用 3 位八进制数值为文件设置权限的时候，第一位数字代表属主权限，第二位数字代表同组用户权限，第三位数字代表其他用户的权限：</p><ul><li>属主：(r=2^2 + w=2^1 + x=2^0 = 7)</li><li>同组用户：(r=2^2 + w=2^1 + x=2^0 = 7)</li><li>其他用户：(r=2^2 + w=0 + x=0 = 4)</li></ul><p>命令如下：</p><pre><code># chmod 774 myfile
</code></pre><p>随着练习时间的推移，你会知道何种情况下使用哪种方式来更改文件的权限模式的效果最好。</p><p>使用 ls -l 详细列举目录详细同样会显示出文件的属主和属组（这个很基本，而且影响到系统文件的访问控制）。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Linux-File-Listing.png" alt="Linux File Listing"></p><p><em>列举 Linux 文件</em></p><p>通过 chown 命令可以对文件的归属权进行更改，可以同时或者分开更改属主和属组。其基本语法为：</p><pre><code># chown user:group file
</code></pre><p>至少要指定用户或者用户组</p><p><strong>举几个例子：</strong></p><p>将文件的属主更改为指定用户：</p><pre><code># chown gacanepa sent
</code></pre><p>同时将文件的属主和属组更改为指定的用户和组：</p><pre><code># chown gacanepa:gacanepa TestFile
</code></pre><p>只将文件的属组更改为指定组。注意组名前的冒号（:）。</p><pre><code># chown :gacanepa email_body.txt
</code></pre><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>作为一个系统管理员，你需要懂得如何创建和恢复备份、如何在系统中搜索文件并更改它们的属性。通过一些技巧，你可以更好地管理系统并避免以后出问题。</p><p>我希望，本文给出的技巧可以帮助你达成管理系统的目标。你可以随时在评论中发表自己的技巧及社区给你带来的益处。</p><p>先行感谢！</p><p>参考链接</p>`,42)),e("ul",null,[e("li",null,[n(l,{href:"https://training.linuxfoundation.org/certification/LFCS"},{default:r(()=>[...t[4]||(t[4]=[i("关于 LFCS",-1)])]),_:1})]),e("li",null,[n(l,{href:"https://training.linuxfoundation.org/certification/why-certify-with-us"},{default:r(()=>[...t[5]||(t[5]=[i("为什么需要 Linux 基金会认证?",-1)])]),_:1})]),e("li",null,[n(l,{href:"https://identity.linuxfoundation.org/user?destination=pid/1"},{default:r(()=>[...t[6]||(t[6]=[i("注册 LFCS 考试",-1)])]),_:1})])]),t[30]||(t[30]=e("hr",null,null,-1)),e("p",null,[t[8]||(t[8]=i("via: ",-1)),n(l,{href:"http://www.tecmint.com/compress-files-and-finding-files-in-linux/"},{default:r(()=>[...t[7]||(t[7]=[i("http://www.tecmint.com/compress-files-and-finding-files-in-linux/",-1)])]),_:1})]),e("p",null,[t[12]||(t[12]=i("作者：",-1)),n(l,{href:"http://www.tecmint.com/author/gacanepa/"},{default:r(()=>[...t[9]||(t[9]=[i("Gabriel Cánepa",-1)])]),_:1}),t[13]||(t[13]=i(" 译者：",-1)),n(l,{href:"https://github.com/GHLandy"},{default:r(()=>[...t[10]||(t[10]=[i("GHLandy",-1)])]),_:1}),t[14]||(t[14]=i(" 校对：",-1)),n(l,{href:"https://github.com/wxy"},{default:r(()=>[...t[11]||(t[11]=[i("wxy",-1)])]),_:1})]),e("p",null,[t[17]||(t[17]=i("本文由 ",-1)),n(l,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[15]||(t[15]=[i("LCTT",-1)])]),_:1}),t[18]||(t[18]=i(" 原创翻译，",-1)),n(l,{href:"https://linux.cn/"},{default:r(()=>[...t[16]||(t[16]=[i("Linux中国",-1)])]),_:1}),t[19]||(t[19]=i(" 荣誉推出",-1))])])}const F=a(m,[["render",f]]);export{y as __pageData,F as default};
